def sch_listener(db):
    if g_enable_prints: print("[sch_listener]: Starting sch listener...")
    while g_sch_listen:
        if db.mp_a.poll(10):
            obj = db.mp_a.recv()
            # print("[sch_listener]: Received=[{}].".format(obj))
            if obj == "STAT":
                if g_enable_prints: db.print_diag_status()
                db.mp_a.send_bytes(b"ACK")
    if g_enable_prints: print("[sch_listener]: Stopped.")


