    def setup_log_dir(self, log_dir):
        self.logdir = log_dir
        if os.path.isdir(self.logdir):
            return
        try:
            os.mkdir(self.logdir)
        except PermissionError:
            print(f"Permission denied to create directory under {self.logdir}")
            self.setup_default_log_dir()

    def setup_default_log_dir(self):
        self.logdir = os.environ.get("HOME") + "/LOGS"
        print(f"Creating default X-Terminator logdir under {self.logdir}")
        if not os.path.isdir(self.logdir):
            os.mkdir(self.logdir)

