    def execute_cmd(self, cmd):
        self.log_debug(f"Executing command: {cmd}")
        out, err, rc = execute_sudo_command(cmd)
        self.log_debug(f"### RET: out={out}, err={err}, rc={rc}")

    def run_cmd(self, cmd):
        self.log_debug(f"Running command: {cmd}")
        out, err, rc = execute_shell_command(cmd)
        self.log_debug(f"### RET: out={out}, err={err}, rc={rc}")
        return (out, err, rc)

    def start_mp_proc(self):
        if not self.mp_proc:
            self.mp_proc = threading.Thread(target=sch_listener, args=(self,))
            self.mp_proc.start()

    def exit(self):
        global g_sch_listen
        g_sch_listen = False
        if self.mp_proc:
            self.mp_proc.join()
            self.mp_proc = None
        self.delete_eth()
        self.print_errors()

    def ip_int2str(self, ip_int):
        ip_addr = ip_address(ip_int)
        return "{}".format(ip_addr)

    def start_schedulers_x2(self, endc=False):
        schs = []
        schs.append([])
        for enb in self.enbs:
            if len(schs[-1]) >= self.MAX_ENB_SCH:
                schs.append([])
            schs[-1].append(enb)

        # Prepare full DB before forking children
        for i, enbs in enumerate(schs):
            self.schedulers_x2.append({"ENBS": enbs, "ID": i})

        # Fork children with full DB
        for enbs in self.schedulers_x2:
            mdict = multiprocessing.Manager().dict()
            mdict["errors"] = 0
            mdict["hb"] = 0
            mdict["id"] = enbs["ID"]
            mdict["status"] = ""
            mdict["req_start_scn"] = False
            mdict["req_stop_scn"] = False
            mdict["req_connect"] = False
            mdict["req_disconnect"] = None
            mdict["req_task"] = ""
            mdict["stat_ls_init"] = 0
            mdict["stat_ls_connected"] = 0
            mdict["stat_ls_closed"] = 0
            mdict["log_screen"] = self.log_screen
            mdict["log_file"] = self.log_file
            sch = x2ap.SchedulerX2(enbs["ID"], mdict, enbs["ENBS"], self, self.mp_b, self.mp_lock, endc)
            sch.start()
            enbs["SCH"] = sch
            enbs["MDICT"] = mdict
            cnt = 600
            while cnt > 0:
                if sch.is_running():
                    break
                cnt -= 1
                time.sleep(0.1)
        time.sleep(2)

