    def generate_enb_yaml(self):
        pci_term = self.vdus[0]['PCI_BEGIN'] - self.vdus[0]['CELL_ID_BEGIN']
        vcu = {
            "vcu1": {
                "enb_ip": self.vdus[0]['FAREND_IP'],
                "type": self.vdus[0]['CELL_DEP_TYPE'],
                "mcc": self.vdus[0]['MCC'],
                "mnc": self.vdus[0]['MNC'],
                "tac": self.vdus[0]['TAC'],
                "sd": self.vdus[0]['SD'],
                "sst": self.vdus[0]['SST'],
                "cells": {},
                "radios": {},
                "dus": {}
            }
        }

        cell_id_min = self.vdus[0]['SERVED_CELLS'][0]['CELL_ID']
        cell_id_max = self.vdus[-1]['SERVED_CELLS'][-1]['CELL_ID']
        init_du_id = self.vdus[0]['GNB_DU_ID']
        du_dict = {}

        for du in self.vdus:
            du_id = du['GNB_DU_ID']
            start_id = du['CELL_ID_BEGIN']
            num_cells = du['NUM_CELLS']
            du_dict.update({du_id: {
                "cell_group": list(range(start_id, start_id + num_cells)),
                "type": "ORAN",
                "ip_addr": du['IP_ADDR']}})

            for i in range(num_cells):
                scope = f"{cell_id_min}..{cell_id_max}"
                cell = {
                    "channels": [
                        {"direction": "TX", "radio": "${ID}", "port": 1},
                        {"direction": "RX", "radio": "${ID}", "port": 1},
                        {"direction": "TX", "radio": "${ID}", "port": 2},
                        {"direction": "RX", "radio": "${ID}", "port": 2},
                    ],
                    "pci": f"${{ID % 1007 + {pci_term}}}",
                    "earfcn_dl": f"${{145800 + 20 * ((ID - {cell_id_min}) // {num_cells})}}",
                    "earfcn_ul": f"${{139800 + 20 * ((ID - {cell_id_min}) // {num_cells})}}",
                    "ch_bw": "5MHz",
                    "tac": du['TAC'],
                    "scs": "15 KHz",
                    "freq_band": du['DL_FREQUENCY_BAND']
                }
                vcu["vcu1"]["cells"][scope] = cell

                radio = {
                    "type": "AVQL",
                    "link_speed": "eCpri25",
                    "protocol_type": "eCPRI",
                    "protocol_version": "72e",
                    "second_endpoint_port_id": 1,
                    "iq_compression": "eCPRI IQ9_E7",
                    "du": f"${{(ID - {cell_id_min}) // {num_cells} + {init_du_id}}}",
                    "port": f"${{((ID - {cell_id_min}) % {num_cells}) + 1}}"
                }
                vcu["vcu1"]["radios"][scope] = radio
        vcu["vcu1"]["dus"] = du_dict

        return vcu

