    def generate_epc_yaml(self):
        if not self.config["CONNECTIONS_AMF"] and self.config["BTS_NGAP_IP_ADDR"] is None:
            raise ValueError(f"No bts_ngap_ip_addr found, please fill parameter in xterm_setup")
        epc_yaml_content = {"upf1": {
                                "ip_addr": "1.2.4.1",
                                "ip_addr_mask": 24,
                                "ngu_ip_addr": "10.0.1.1"
                            },
                            "uesim_ip_configuration": {
                                "workstation_ip_addr": "192.168.200.126",
                                "netmask": "255.255.255.0",
                                "lte_network_gw": "10.0.2.1",
                                "ss_ip_addr_pool": "185.4.0.0/16",
                                "ue_ip_addr_pool": "186.4.0.0/18"}
                            }

        amfs_dict = {}
        tac_list = self.get_tac_list()

        if not self.amfs[0]['AMF_IP_ADDR']:
            raise Exception("Cannot generate config due to lack of AMF params. Please provide connections_amf param in "
                            "xterm_setup")

        for amf_id, amf in enumerate(self.amfs, 1):
            amfs_dict.update({f'amf{amf_id}': {
                "ip_addr": amf['AMF_IP_ADDR'],
                "mcc": amf['AMF_MCC'],
                "mnc": amf['AMF_MNC'],
                "amf_region id": amf['AMF_REGION_ID'],
                "tac_list": tac_list,
                "set_id": amf['AMF_SET_ID'],
                "pointer": amf['AMF_POINTER'],
                "ngc_ip_addr": amf['AMF_IP_FAREND'],
            }})

        epc_yaml_content.update(amfs_dict)
        return epc_yaml_content

